javascript-14.solution:
function parsePlants(text) {
  try {
    const data = JSON.parse(text);
    if (
      !Array.isArray(data) ||
      !data.every((p) => p && typeof p.name === "string")
    )
      return { ok: false, error: "Expected plants with names" };
    return { ok: true, data };
  } catch {
    return { ok: false, error: "Invalid JSON" };
  }
}

