javascript-23.solution:
function cartReducer(cart, action) {
  if (action.type !== "add" && action.type !== "remove") return cart;
  const next = { ...cart };
  const count = Math.max(
    0,
    (cart[action.id] || 0) + (action.type === "add" ? 1 : -1),
  );
  if (count) next[action.id] = count;
  else delete next[action.id];
  return next;
}

