function updateTasks(tasks, action) {
  if (action.type === "add") {
    const title = action.title.trim();
    if (!title || tasks.some((task) => task.id === action.id))
      return tasks;
    return [...tasks, { id: action.id, title, done: false }];
  }
  if (action.type === "toggle")
    return tasks.map((task) =>
      task.id === action.id ? { ...task, done: !task.done } : task,
    );
  if (action.type === "remove")
    return tasks.filter((task) => task.id !== action.id);
  return tasks;
}
function visibleTasks(tasks, filter) {
  return tasks.filter(
    (task) =>
      filter === "all" || (filter === "done" ? task.done : !task.done),
  );
}
if (typeof document !== "undefined" && document.getElementById) {
  let tasks = [];
  let filter = "all";
  let nextId = 1;
  const list = document.getElementById("tasks");
  const form = document.getElementById("new-task");
  const title = document.getElementById("title");
  function render() {
    list.replaceChildren();
    for (const task of visibleTasks(tasks, filter)) {
      const row = document.createElement("li");
      const toggle = document.createElement("button");
      toggle.textContent = (task.done ? "✓ " : "○ ") + task.title;
      toggle.setAttribute("aria-pressed", String(task.done));
      toggle.onclick = () => {
        tasks = updateTasks(tasks, { type: "toggle", id: task.id });
        render();
      };
      const remove = document.createElement("button");
      remove.textContent = "Remove";
      remove.setAttribute("aria-label", "Remove " + task.title);
      remove.onclick = () => {
        tasks = updateTasks(tasks, { type: "remove", id: task.id });
        render();
      };
      row.append(toggle, remove);
      list.append(row);
    }
    document.getElementById("status").textContent =
      tasks.filter((task) => task.done).length +
      " / " +
      tasks.length +
      " complete";
  }
  form.onsubmit = (event) => {
    event.preventDefault();
    tasks = updateTasks(tasks, {
      type: "add",
      id: nextId++,
      title: title.value,
    });
    title.value = "";
    render();
  };
  document.getElementById("filter").onchange = (event) => {
    filter = event.target.value;
    render();
  };
  render();
}
console.log(
  visibleTasks(
    updateTasks([], { type: "add", id: 1, title: "Ship my app" }),
    "active",
  ),
);

