javascript-32.solution:
const products = [
  { id: "basil", name: "Basil", price: 450 },
  { id: "mint", name: "Mint", price: 350 },
  { id: "fern", name: "Fern", price: 1200 },
];
function changeCart(cart, id, delta) {
  if (!products.some((product) => product.id === id)) return cart;
  const quantity = Math.max(0, (cart[id] || 0) + delta);
  const next = { ...cart };
  if (quantity === 0) delete next[id];
  else next[id] = quantity;
  return next;
}
function cartTotal(cart) {
  return products.reduce(
    (sum, product) => sum + product.price * (cart[product.id] || 0),
    0,
  );
}
function searchProducts(query) {
  return products.filter((product) =>
    product.name.toLowerCase().includes(query.trim().toLowerCase()),
  );
}
if (typeof document !== "undefined" && document.getElementById) {
  let cart = {};
  let query = "";
  const catalog = document.getElementById("catalog");
  const basket = document.getElementById("basket");
  function render() {
    catalog.replaceChildren();
    basket.replaceChildren();
    for (const product of searchProducts(query)) {
      const card = document.createElement("article");
      const name = document.createElement("h2");
      name.textContent = product.name;
      const price = document.createElement("p");
      price.textContent = "€" + (product.price / 100).toFixed(2);
      const add = document.createElement("button");
      add.textContent = "Add " + product.name;
      add.onclick = () => {
        cart = changeCart(cart, product.id, 1);
        render();
      };
      card.append(name, price, add);
      catalog.append(card);
    }
    for (const product of products.filter(
      (product) => cart[product.id],
    )) {
      const row = document.createElement("li");
      row.textContent = product.name + " × " + cart[product.id];
      const remove = document.createElement("button");
      remove.textContent = "Remove one " + product.name;
      remove.onclick = () => {
        cart = changeCart(cart, product.id, -1);
        render();
      };
      row.append(remove);
      basket.append(row);
    }
    document.getElementById("total").textContent =
      "Total: €" + (cartTotal(cart) / 100).toFixed(2);
  }
  document.getElementById("search").oninput = (event) => {
    query = event.target.value;
    render();
  };
  document.getElementById("clear").onclick = () => {
    cart = {};
    render();
  };
  render();
}
console.log(cartTotal(changeCart({}, "basil", 2)));

