class Stock {
  private quantity = 0;
  get current(): number {
    return this.quantity;
  }
  receive(amount: number): void {
    if (Number.isInteger(amount) && amount > 0) this.quantity += amount;
  }
  sell(amount: number): boolean {
    if (
      !Number.isInteger(amount) ||
      amount <= 0 ||
      amount > this.quantity
    )
      return false;
    this.quantity -= amount;
    return true;
  }
}

