typescript-29.solution:
type DocumentV1 = { version: 1; title: string };
function readDocument(text: string): DocumentV1 | null {
  try {
    const value: unknown = JSON.parse(text);
    if (typeof value !== "object" || value === null) return null;
    const d = value as Record<string, unknown>;
    return d.version === 1 && typeof d.title === "string"
      ? { version: 1, title: d.title }
      : null;
  } catch {
    return null;
  }
}

