typescript-31.solution:
type Product = {
  id: string;
  name: string;
  price: number;
  stock: number;
};
type Change = { id: string; delta: number };
function adjustStock(
  items: readonly Product[],
  change: Change,
): Product[] {
  return items.map((item) =>
    item.id === change.id
      ? { ...item, stock: Math.max(0, item.stock + change.delta) }
      : item,
  );
}
function inventoryValue(items: readonly Product[]): number {
  return items.reduce((sum, item) => sum + item.price * item.stock, 0);
}
function findProducts(
  items: readonly Product[],
  query: string,
): Product[] {
  return items.filter((item) =>
    item.name.toLowerCase().includes(query.trim().toLowerCase()),
  );
}
if (typeof document !== "undefined") {
  let items: Product[] = [
    { id: "basil", name: "Basil", price: 450, stock: 3 },
    { id: "mint", name: "Mint", price: 350, stock: 2 },
  ];
  const list = document.getElementById("inventory")!;
  const query = document.getElementById("query") as HTMLInputElement;
  function render(): void {
    list.replaceChildren();
    for (const item of findProducts(items, query.value)) {
      const row = document.createElement("article");
      const name = document.createElement("h2");
      name.textContent = item.name;
      const count = document.createElement("p");
      count.textContent =
        item.stock + " in stock · €" + (item.price / 100).toFixed(2);
      const add = document.createElement("button");
      add.textContent = "Receive one " + item.name;
      add.onclick = () => {
        items = adjustStock(items, { id: item.id, delta: 1 });
        render();
      };
      const sell = document.createElement("button");
      sell.textContent = "Sell one " + item.name;
      sell.disabled = item.stock === 0;
      sell.onclick = () => {
        items = adjustStock(items, { id: item.id, delta: -1 });
        render();
      };
      row.append(name, count, add, sell);
      list.append(row);
    }
    document.getElementById("value")!.textContent =
      "Inventory value: €" + (inventoryValue(items) / 100).toFixed(2);
  }
  query.oninput = render;
  render();
}
console.log(
  inventoryValue([
    { id: "basil", name: "Basil", price: 450, stock: 3 },
  ]),
);

