typescript-32.solution:
type Session = {
  id: string;
  title: string;
  capacity: number;
  booked: number;
};
type BookingResult =
  { ok: true; sessions: Session[] } | { ok: false; error: string };
function reserve(
  sessions: readonly Session[],
  id: string,
  seats: number,
): BookingResult {
  const session = sessions.find((item) => item.id === id);
  if (!session) return { ok: false, error: "Unknown session" };
  if (!Number.isInteger(seats) || seats < 1)
    return { ok: false, error: "Choose a positive whole number" };
  if (session.booked + seats > session.capacity)
    return { ok: false, error: "Not enough seats" };
  return {
    ok: true,
    sessions: sessions.map((item) =>
      item.id === id ? { ...item, booked: item.booked + seats } : item,
    ),
  };
}
function seatsLeft(session: Session): number {
  return Math.max(0, session.capacity - session.booked);
}
if (typeof document !== "undefined") {
  let sessions: Session[] = [
    { id: "seeds", title: "Seed starting", capacity: 6, booked: 0 },
    { id: "pots", title: "Container gardens", capacity: 4, booked: 0 },
  ];
  const list = document.getElementById("sessions")!;
  const form = document.getElementById("booking") as HTMLFormElement;
  const choice = document.getElementById(
    "session",
  ) as HTMLSelectElement;
  const seats = document.getElementById("seats") as HTMLInputElement;
  const status = document.getElementById("status")!;
  function render(): void {
    list.replaceChildren();
    for (const session of sessions) {
      const row = document.createElement("article");
      const heading = document.createElement("h2");
      heading.textContent = session.title;
      const count = document.createElement("p");
      count.textContent = seatsLeft(session) + " seats available";
      row.append(heading, count);
      list.append(row);
    }
  }
  form.onsubmit = (event) => {
    event.preventDefault();
    const result = reserve(sessions, choice.value, Number(seats.value));
    if (result.ok) {
      sessions = result.sessions;
      status.textContent = "Booking confirmed";
      render();
    } else status.textContent = result.error;
  };
  render();
}
console.log(
  reserve(
    [{ id: "seeds", title: "Seeds", capacity: 6, booked: 1 }],
    "seeds",
    2,
  ),
);

