"use client";
import { useState } from "react";
import { toggle, remaining, type Task } from "../lib/tasks";
export default function Board() {
  const [tasks, setTasks] = useState<Task[]>([
    { id: 1, title: "Plan the app", done: false },
    { id: 2, title: "Build the UI", done: false },
    { id: 3, title: "Test the edge cases", done: false },
  ]);
  const [title, setTitle] = useState("");
  const [filter, setFilter] = useState("all");
  const visible = tasks.filter(
    (task) =>
      filter === "all" || (filter === "done" ? task.done : !task.done),
  );
  return (
    <main>
      <h1>Project Board</h1>
      <p role="status">{remaining(tasks)} tasks left</p>
      <ul>
        {visible.map((task) => (
          <li key={task.id}>
            <button
              aria-pressed={task.done}
              onClick={() =>
                setTasks((items) => toggle(items, task.id))
              }
            >
              {task.done ? "Undo " : "Complete "}
              {task.title}
            </button>
            <button
              onClick={() =>
                setTasks((items) =>
                  items.filter((item) => item.id !== task.id),
                )
              }
            >
              Remove {task.title}
            </button>
          </li>
        ))}
      </ul>
      <form
        onSubmit={(event: { preventDefault(): void }) => {
          event.preventDefault();
          if (title.trim()) {
            setTasks((items) => [
              ...items,
              { id: Date.now(), title: title.trim(), done: false },
            ]);
            setTitle("");
          }
        }}
      >
        <label htmlFor="new-title">New task</label>
        <input
          id="new-title"
          value={title}
          onChange={(event: { target: { value: string } }) =>
            setTitle(event.target.value)
          }
        />
        <button type="submit">Add task</button>
      </form>
      <label htmlFor="view">View</label>
      <select
        id="view"
        value={filter}
        onChange={(event: { target: { value: string } }) =>
          setFilter(event.target.value)
        }
      >
        <option value="all">All</option>
        <option value="active">Active</option>
        <option value="done">Done</option>
      </select>
    </main>
  );
}

