"use client";
import { useState } from "react";
import { total, addExpense, type Expense } from "../lib/budget";
export default function Budget() {
  const [expenses, setExpenses] = useState<Expense[]>([
    { id: 1, title: "Seeds", cents: 450 },
  ]);
  const [title, setTitle] = useState("");
  const [amount, setAmount] = useState("");
  const [message, setMessage] = useState("");
  return (
    <main>
      <h1>Small Budget</h1>
      <p role="status">Total: €{(total(expenses) / 100).toFixed(2)}</p>
      <button
        onClick={() =>
          setExpenses((items) =>
            addExpense(items, {
              id: Date.now(),
              title: "Plant pot",
              cents: 300,
            }),
          )
        }
      >
        Add a €3 plant pot
      </button>
      <ul>
        {expenses.map((expense) => (
          <li key={expense.id}>
            {expense.title}: €{(expense.cents / 100).toFixed(2)}
            <button
              onClick={() =>
                setExpenses((items) =>
                  items.filter((item) => item.id !== expense.id),
                )
              }
            >
              Remove {expense.title}
            </button>
          </li>
        ))}
      </ul>
      <form
        onSubmit={(event: { preventDefault(): void }) => {
          event.preventDefault();
          const cents = Math.round(Number(amount) * 100);
          if (!title.trim() || !Number.isFinite(cents) || cents <= 0) {
            setMessage("Enter a title and positive amount");
            return;
          }
          setExpenses((items) =>
            addExpense(items, { id: Date.now(), title, cents }),
          );
          setTitle("");
          setAmount("");
          setMessage("Expense added");
        }}
      >
        <label htmlFor="expense-title">Expense title</label>
        <input
          id="expense-title"
          value={title}
          onChange={(event: { target: { value: string } }) =>
            setTitle(event.target.value)
          }
        />
        <label htmlFor="amount">Amount in euros</label>
        <input
          id="amount"
          type="number"
          min="0.01"
          step="0.01"
          value={amount}
          onChange={(event: { target: { value: string } }) =>
            setAmount(event.target.value)
          }
        />
        <button>Add expense</button>
      </form>
      <p role="status">{message}</p>
    </main>
  );
}

