export type Expense = { id: number; title: string; cents: number };
export function total(expenses: readonly Expense[]): number {
  return expenses.reduce((sum, expense) => sum + expense.cents, 0);
}
export function addExpense(
  expenses: readonly Expense[],
  expense: Expense,
): Expense[] {
  if (
    !expense.title.trim() ||
    !Number.isInteger(expense.cents) ||
    expense.cents <= 0 ||
    expenses.some((item) => item.id === expense.id)
  )
    return [...expenses];
  return [...expenses, { ...expense, title: expense.title.trim() }];
}
